from pathlib import Path
import json,re,hashlib
p=Path('design-handoff/proposals/2026-11-26-v4-art-library');out=Path('design-handoff/proposals/2026-11-27-v4-high-frequency-objects');data=json.loads((p/'inventory.json').read_text())
patterns={'yaprak':r'\byapra[kğ]\w*','örtü':r'\börtü\w*','yatak/yastık/döşek':r'\b(?:yata[kğ]|yastı[kğ]|döşe[kğ])\w*','dal':r'\bdal(?:ın\w*|a|da|dan|ı|lar\w*)?\b','toprak':r'\btopra[kğ]\w*','minder':r'\bminder\w*','ağaç/gövde':r'\b(?:ağa[çc]|gövde)\w*','mendil':r'\bmendil\w*','kök':r'\bkök\w*','tahta işaret':r'\btahta\w*','taş':r'\btaş(?:ın|a|ta|tan|ı|lar\w*)?\b','damla':r'\bdamla\w*'}
rows=[]
for label,pattern in patterns.items():
 matches=[r for r in data['pages'] if re.search(pattern,r['templateText'].lower())]
 rows.append({'subjectGroup':label,'bookCount':len({r['bookID'] for r in matches}),'pageCount':len(matches),'bookPrevalence':len({r['bookID'] for r in matches})/90,'regex':pattern,'interpretation':'noun-form lexical candidate; temporal/physical review required; NOT runtime probability or authorized coverage','sources':[{k:r[k] for k in ['bookID','number','templateID','templateSHA256']} for r in matches]})
rows.sort(key=lambda r:(-r['bookCount'],-r['pageCount']))
(out/'frequency-audit.json').write_text(json.dumps({'packageVersion':data['packageVersion'],'payloadSHA256':data['payloadSHA256'],'books':90,'pages':720,'method':'Explicit Turkish noun-form filters over pinned template text; an inventory priority proxy only. No generation sampling. No scene-presence guarantee.','rankings':rows},ensure_ascii=False,indent=2)+'\n')
lines=['# V4 yaygın nesneler — öncelik hesabı','','27 Kasım 2026. 90 kitap / 720 sayfalık pinli V4 metni esas alındı. Kitap yaygınlığı, o nesnenin en az bir kez sözcüksel olarak geçtiği kitap sayısıdır; motorun gerçek seçilme olasılığı değildir. Mod/arkadaş tercihi ve tekrar soğuması gerçek dağılımı değiştirebilir.','','| Nesne grubu | Kitap | Sayfa |','|---|---:|---:|']
for r in rows:lines.append(f"| {r['subjectGroup']} | {r['bookCount']}/90 | {r['pageCount']} |")
lines+=['','Otomatik etiketlerdeki dalmak/dal, yuvarlanmak/yuva, taşımak/taş ve örtü/tüy karışmaları kullanılmadı. Sayılar yine semantik yayın incelemesi değildir: hedef, anı, olumsuzluk ve karakter aksesuarı ayrımı her eşleşmede yapılmalıdır. Yaprak grubu Kestane’nin kimlik yaprağını da içerebilir; genel yaprak asset’i onun yerine otomatik geçmez.','','## Paket yaklaşımı','','En yaygın gruplar için yeni genel çizimler ve mevcut durum çizimleri birleştirilir. Tek bir genel yaprak; damla, örtülü yaprak veya dala temas olayının yerine geçmez. Minder/örtü gibi önceki seçili görseller yeniden üretilmeden kullanılır. Ana gruplar dışındaki küçük tüy destek varlığıdır, sıklık sıralamasını yükseltmek için sayılmamıştır.','','Yeni üretim: yeşil yaprak, kuru yaprak, yastık, alçak döşek, dal, gövde/toprak, çatallı kök ve yuvarlak/uzamış damla. Seçilmiş mevcut nesne durumları da paylaşım paketine alınır.','','App/motor/metin değişmez. Kaynak SHA içeren listeler aday eşleme yerleridir. Sahne bazında yayın onayı ve gerçek runtime kapsama ölçümü ayrıca gerekir.']
(out/'FREQUENCY_REPORT.md').write_text('\n'.join(lines)+'\n')
print([(r['subjectGroup'],r['bookCount']) for r in rows])
